-- The Demo School: sample students, fees and receipts for trying the app on the live site
-- (owner's request, 2026-11-20). It is marked is_demo, so "All schools" leaves it out of every
-- list, total and report; choose "Demo School" at sign-in or in the school switcher to see it.
-- The admin can close it under Branches. Receipts are never deleted, so its sample receipts
-- stay, under their own numbers (DEMO-00001 ...), apart from the real schools.
--
-- Loaded only on a database that has the school from migration 0003 and no school coded DEMO
-- yet. The rows below are generated by seed/demo/build.sh from the app's own fee rules; do
-- not edit them by hand.

INSERT INTO settings (key, value)
SELECT 'demo.loading', '1'
WHERE EXISTS (SELECT 1 FROM users WHERE username = 'admin@sps.com')
  AND EXISTS (SELECT 1 FROM academic_sessions WHERE name = '2026-27')
  AND NOT EXISTS (SELECT 1 FROM branches WHERE code = 'DEMO');

INSERT INTO branches (name, code, address, phone, active, is_demo, created_at)
SELECT 'Demo School', 'DEMO', 'Sample data for trying the app', '', 1, 1,
       strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE EXISTS (SELECT 1 FROM settings WHERE key = 'demo.loading');

INSERT INTO sections (branch_id, class_id, name)
SELECT (SELECT id FROM branches WHERE code = 'DEMO'), id, 'A' FROM classes
WHERE EXISTS (SELECT 1 FROM settings WHERE key = 'demo.loading');

-- Same fee chart as Kamalganj.
INSERT INTO fee_rates
  (session_id, branch_id, class_id, admission_type, registration, admission, board, annual,
   practical, practical_alt, tbdb, monthly, updated_at)
SELECT r.session_id, (SELECT id FROM branches WHERE code = 'DEMO'), r.class_id, r.admission_type,
       r.registration, r.admission, r.board, r.annual, r.practical, r.practical_alt, r.tbdb,
       r.monthly, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM fee_rates r
WHERE r.branch_id = (SELECT id FROM branches WHERE code = 'KMG')
  AND r.session_id = (SELECT id FROM academic_sessions WHERE name = '2026-27')
  AND EXISTS (SELECT 1 FROM settings WHERE key = 'demo.loading');

INSERT INTO audit_log (at, user_name, action, entity, summary)
SELECT strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), 'System', 'create', 'branch',
       'Added the Demo School with sample students, fees and receipts'
WHERE EXISTS (SELECT 1 FROM settings WHERE key = 'demo.loading');
